def candidate_design():
    from sampling import models
    from alignment import parameters
    from supervisor_compliance import numeric_attributes
    p,d,_=models()
    detector_attributes=numeric_attributes(FMD.read_text(encoding='utf-8'))
    detectors={r['checkpoint']:r for r in load(STUDY/'protocol.json')['detectors']}
    rows=[]
    for checkpoint,architecture in [('ck01','YOLO26'),('ck05','YOLOv8'),('ck06','YOLO11')]:
        spec=detectors[checkpoint]
        if sha256(Path(spec['path']))!=spec['sha256']:raise ValueError('Checkpoint SHA differs.')
        for resolution_feature in ('Infer640','Infer1280'):
            value=detector_attributes[(resolution_feature,'imgsz')]
            if value!=int(value):raise ValueError('Input resolution must be an integer UVL attribute.')
            resolution=int(value)
            declared=d.declared_profile_configuration(architecture,'Small','VisDrone_FT','Train1280',resolution,'FP32','FullFrame','NMS')
            for blur in ('None','Motion_k21'):
                for jpeg in ('JPEG_q25','JPEG_q50','JPEG_q75'):
                    leaves=sorted(['Normal',jpeg]+([] if blur=='None' else [blur]))
                    if not p.valid_leaves(leaves):raise ValueError('Illegal candidate configuration.')
                    identity=p.configuration_id(leaves)+'__'+checkpoint+'_R'+str(resolution)
                    rows.append({'pair_id':identity,'FM_P_ID':p.configuration_id(leaves),
                        'FM_D_declared_ID':declared['configuration_id'],'checkpoint':checkpoint,
                        'checkpoint_sha256':spec['sha256'],'resolution':resolution,'blur':blur,'jpeg':jpeg,
                        'selected_FM_P':leaves,'UVL_attributes':parameters(FMP,leaves),
                        'declared_FM_D':declared['selected_features'],'training_augmentation_evidence':'UNKNOWN_RUNTIME_ACTIVATION',
                        'split':'VisDrone2019-DET-val','images':548,'precision':'FP32','status':'PLANNED',
                        'student_review':'NEEDS_SCIENTIFIC_REVIEW',
                        'runtime_binding_status':'MOTION_ORIENTATION_REVIEW_REQUIRED' if blur!='None' else 'PDF_ATTRIBUTES_COMPLETE_FOR_SELECTED_EFFECTS'})
    if len(rows)!=36 or len({r['pair_id'] for r in rows})!=36:raise ValueError('Candidate factorial is incomplete.')
    return rows


